def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s functions, in a fresh test-owned tree; every name they read a recorder on `t`."""
    import dataclasses, json, os, shutil, tempfile
    from pathlib import Path as _P
    from types import SimpleNamespace
    calls: list = []
    tmp = _P(tempfile.mkdtemp(prefix="syrd430-")).resolve()
    repo = _P(t.__file__).resolve().parent.parent

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, (set, frozenset)):
            return sorted(norm(v) for v in value)
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if isinstance(value, _P):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP").replace(str(repo), "REPO")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        if isinstance(value, SimpleNamespace):
            return f"NAMESPACE {getattr(value, 'label', '?')}"
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {type(value).__name__: {f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if callable(value):
            return f"CALLABLE {getattr(value, '__module__', '?')}.{getattr(value, '__qualname__', '?')}"
        return repr(value)

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    place = lambda v: (tmp / v[2:]) if isinstance(v, str) and v.startswith("@/") else v
    deep = lambda v: {k: deep(x) for k, x in v.items()} if isinstance(v, dict) else [deep(x) for x in v] if isinstance(v, list) else (str(place(v)) if isinstance(v, str) and v.startswith("@/") else v)
    names = [*FUNCTIONS, "SUPPORTED_CONFIG_CLI_NAMES", "RoleConfig", "current_user_name", "_expand_path", "_load_json", "_command_name",
             "DEFAULT_MODEL_ARG_BY_CLI", "DEFAULT_RESUME_FLAG_BY_CLI", "DEFAULT_RESUME_MODE_BY_CLI", "DEFAULT_RESUME_SUBCOMMAND_BY_CLI",
             "ProjectBoardProvision", "build_plan", "migrate_plan_document", "plan_field_names", "role_tooling_staging_dir",
             "unresolved_plan_field_reason"]  # SYRD-543
    saved = {n: getattr(t, n) for n in names}
    saved_geteuid, saved_cwd = os.geteuid, os.getcwd()
    try:
        under = {n: getattr(holder, n) for n in FUNCTIONS}

        def passthrough(name):
            def f(*args, **kwargs):
                note(name, *args, **kwargs)
                return saved[name](*args, **kwargs)
            return f

        def staging(project):
            note("role_tooling_staging_dir", project)
            return str(tmp / "staging" / project)

        if spec.get("staged"):
            hooks = tmp / "staging" / "p430" / "git-template" / "hooks"
            hooks.mkdir(parents=True)
            if spec["staged"] is True:
                (hooks / "pre-commit").write_text("#!/bin/sh\n", encoding="utf-8")

        def migrate(document, *, reference):
            note("migrate_plan_document", document, reference=reference)
            stub = spec["stub"]
            return dict(stub["fields"]), list(stub["added"]), list(stub["unresolved"])

        def record(**fields):
            note("ProjectBoardProvision", **fields)
            return SimpleNamespace(label="provision record")

        def build(**kwargs):
            note("build_plan", **kwargs)
            if spec.get("build") == "refuse":
                raise SystemExit("syrd430: the builder refuses")
            return SimpleNamespace(label="reference plan")

        on_launcher = {n: passthrough(n) for n in (*FUNCTIONS, "_expand_path", "_load_json", "_command_name", "build_plan",
                                                   "migrate_plan_document", "plan_field_names", "unresolved_plan_field_reason")}
        on_launcher.update({
            "current_user_name": lambda: note("current_user_name") or "syrd430-me",
            "role_tooling_staging_dir": staging,
        })
        if "stub" in spec:
            on_launcher.update(migrate_plan_document=migrate, plan_field_names=lambda: note("plan_field_names") or ("project",),
                               ProjectBoardProvision=record)
        if "build" in spec:
            on_launcher["build_plan"] = build
        stand = {"RECORD": lambda **fields: note("RoleConfig", **fields) or SimpleNamespace(label="role record"),
                 "EXPAND": lambda value, *, base: note("_expand_path", value, base=base) or _P("/syrd430/expanded"),
                 "NAME": lambda value: note("_command_name", value) or "claude",
                 "BOOL": lambda value, *, field, role: note("_bool_value", value, field=field, role=role) or "BOOL",
                 "BOARD": lambda config, role, session_role_map: note("_role_board_env", config, role, session_role_map) or {"SYRD430": "board"},
                 "TEMPLATE": lambda project: note("role_git_template_env", project) or {"SYRD430": "template", "T": "1"}}
        on_launcher.update({k: stand.get(v, v) if isinstance(v, str) else v for k, v in spec.get("launcher", {}).items()})
        for n, f in on_launcher.items():
            setattr(t, n, f)
        os.geteuid = lambda: 1430
        os.chdir(repo)

        def role(raw, **kw):
            return under["_role_from_json"]("p430", deep(raw), base=tmp / "base", default_workdir=kw.get("default_workdir", tmp / "default"))

        def config(**over):
            base = {"project": "p430", "project_name": "P 430", "ticket_prefix": "PFT", "board_url": "http://127.0.0.1:24300",
                    "board_socket": "/run/p430/board.sock", "role_state_isolation": True, "run_as_user": "", "upstream_report_url": "",
                    "upstream_report_token_file": "", "roles": [], "label": "config"}
            return SimpleNamespace(**{**base, **deep(over)})

        call = spec["call"]
        try:
            if call == "string_list":
                got = under["_string_list"](spec["value"], field="extra_args", role="r")
            elif call == "bool_value":
                got = under["_bool_value"](spec["value"], field="yolo", role="r")
            elif call == "role":
                got = role(spec["raw"], **({"default_workdir": None} if "default_workdir" in spec else {}))
            elif call == "board_env":
                others = [SimpleNamespace(role=r, run_as_user=a) for r, a in spec.get("others", [])]
                cfg = config(**spec["config"])
                cfg.roles = others
                got = under["_role_board_env"](cfg, SimpleNamespace(role="main"), {"p430-main": "main", "p430-app": "app"})
            elif call == "git_template":
                got = under["role_git_template_env"]("p430")
            elif call == "with_env":
                roles = [dataclasses.replace(saved["_role_from_json"]("p430", {"role": r, "cli": "codex", "tmux_session": f"s-{r}"},
                                                                      base=tmp, default_workdir=tmp), env=dict(spec.get("role_env", {})))
                         for r in ("main", "app")]
                got = under["_with_project_board_env"](config(), roles)
            elif call == "owner_home":
                got = under["_recorded_owner_home"](spec["raw"])
            elif call == "reference":
                got = under["_plan_migration_reference"](deep(spec["raw"]))
            elif call == "provision":
                path = tmp / "provision" / "plan.json"
                path.parent.mkdir()
                if spec.get("plan") in ("real", "old"):
                    plan = saved["build_plan"](project="p430", owner_user="p430-agent", owner_home=tmp / "home" / "p430", port=24300,
                                               database="p430_board", commit_git_dir=str(tmp / "commits.git"))
                    document = json.loads(json.dumps(dataclasses.asdict(plan), default=str))
                    for name in spec.get("drop", ()):
                        document.pop(name, None)
                    if spec["plan"] == "old":
                        for name in ("canary_unit", "role_accounts", "owner_home", *(("commit_git_dir",) if "supplied" in spec else ())):
                            document.pop(name, None)
                        document["board_root"] = str(tmp / "home" / "p430" / "p430-ticketboard-live")
                elif spec.get("plan") == "list":
                    document = ["not", "an", "object"]
                else:
                    document = {"project": "p430", "owner_user": "p430-agent", "owner_home": str(tmp / "home" / "p430")}
                path.write_text(json.dumps(document), encoding="utf-8")
                migrated = [] if spec.get("migrated") else None
                kwargs = {"migrated": migrated} if migrated is not None else {}
                if "supplied" in spec:
                    kwargs["supplied"] = {k: str(place(v)) for k, v in spec["supplied"].items()}
                if spec.get("document"):
                    kwargs["document"] = document
                parse = t._project_board_provision_from_json if spec.get("via") == "launcher" else under["_project_board_provision_from_json"]
                result = parse(path, **kwargs)
                got = {"record": result, "migrated": migrated}
            else:
                (tmp / "cfg").mkdir()
                document = {"project": "p430", "project_name": "P 430", "ticket_prefix": "PFT", "session_dir": str(tmp / "sessions"),
                            "layout": "layout.json", "repository": str(tmp / "repo"),
                            "roles": [{"role": "director", "cli": "claude", "slot": 0}, {"role": "main", "cli": "codex", "slot": 1,
                                                                                         "workdir": "main-work", "env": {"MINE": "1"}}]}
                if spec.get("bad_role"):
                    document["roles"].append({"role": "ops", "cli": "gemini"})
                got = t.load_project_config("p430", tmp / "cfg" / "p430.json", document=document)
            result = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            result = {"raised": type(exc).__name__, "message": norm(str(exc))}
        return {"result": result, "calls": calls}
    finally:
        os.chdir(saved_cwd)
        os.geteuid = saved_geteuid
        for n, f in saved.items():
            setattr(t, n, f)
        shutil.rmtree(tmp)
