def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def seams(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    def role(label):
        return result(label)["RoleConfig"]

    check(result("string list: none") == [] and result("boolean: none") is False
          and result("string list: a string")["message"] == "role r extra_args must be a JSON string list"
          and result("boolean: one")["message"] == "role r yolo must be a JSON boolean",
          "an absent list or boolean is empty or false; a wrong type is refused, word for word")
    check(result("role: a missing role name")["message"] == "team launcher role entry missing role"
          and result("role: a CLI list holding a number")["message"] == "role r must define cli as a string or string list"
          and result("role: env that is not an object")["message"] == "role main env must be a JSON object"
          and result("role: an unsupported CLI")["message"] == "role r cli 'gemini' is not supported; supported clis: agy, claude, codex, hermes",
          "the role refusals, word for word")
    minimal = role("role: a minimal role")
    check(minimal["tmux_session"] == "p430-main" and minimal["target"] == "p430-main:0.0" and minimal["cli"] == ["codex", "--full-auto"]
          and minimal["workdir"] == "TMP/default" and role("role: no workdir and no default: the current directory")["workdir"] == "REPO",
          "the session and target default from the project and role, the CLI string is split, the workdir defaults")
    full = role("role: a role with every field")
    check(full["role"] == "app" and full["slot"] == 2 and full["workdir"] == "TMP/base/rel/app" and full["env"] == {"2": "b", "A": "1"}
          and full["model_arg"] == "-m" and full["resume_subcommand"] == "again" and full["run_as_user"] == "p430-app",
          "every field is read, stripped and typed; a relative workdir is under the config's base; env keys and values are strings")
    fallback = role("role: the resume and model tables rebound empty: every fallback")
    check([fallback[k] for k in ("resume_mode", "resume_flag", "resume_subcommand", "model_arg")] == ["flag", "--resume", "resume", "--model"],
          "a CLI missing from the tables falls back to flag, --resume, resume and --model")
    rebound = role("role: the resume and model defaults rebound on the launcher")
    check(rebound["resume_mode"] == "syrd430-mode" and rebound["resume_flag"] == "--syrd430" and rebound["model_arg"] == "--syrd430-model"
          and result("role: the supported CLIs rebound on the launcher")["message"].endswith("supported clis: claude")
          and result("role: the role record rebound on the launcher") == "NAMESPACE role record"
          and role("role: a sibling stood in on the launcher")["detached"] == "BOOL",
          "the CLI tables, the record and the siblings are the launcher's at call time")
    iso, legacy = result("board env: isolated roles"), result("board env: legacy roles bound to other accounts")
    check(iso["TICKET_BOARD_PROCESS_AUTHORITY"] == "1" and "TICKET_BOARD_ROLE_ACCOUNTS" not in iso
          and legacy["TICKET_BOARD_ROLE_ACCOUNTS"] == "app=p430-app" and legacy["SWITCHYARD_PROJECT_OWNER"] == "p430-owner"
          and result("board env: legacy roles, no owner: the current user")["TICKET_BOARD_ROLE_ACCOUNTS"] == "ops=p430-ops"
          and result("board env: an upstream report and its token")["TICKET_BOARD_TENANT_REPORT_TOKEN_FILE"] == "TMP/report.env",
          "isolation asks for process authority; legacy routing names only accounts other than the owner (or the current user)")
    check(result("git template: staged") == {"GIT_TEMPLATE_DIR": "TMP/staging/p430/git-template"}
          and result("git template: not staged") == result("git template: a directory but no hook") == {},
          "the template only once its pre-commit hook is staged")
    envs = [r["RoleConfig"]["env"] for r in result("the role's own env wins over the template, the board env over both")]
    check(all(e["GIT_TEMPLATE_DIR"] == "/mine" and e["TICKET_BOARD_URL"] == "http://127.0.0.1:24300" for e in envs),
          "the role's own env over the template, the board env over both")
    check(result("owner home: from the board root") == "/srv/p430" and result("owner home: a board root for another project") == ""
          and result("reference: no owner user") is None and result("reference: the builder refuses") is None
          and "port" not in GOLDEN["reference: a port that is a boolean is not recorded"]["calls"][-1][2],
          "the owner home is recorded or disclosed by the board root, never guessed; no reference without an identity")
    check(result("provision: an older plan, its fields migrated and reported")["migrated"] == ["canary_unit", "role_accounts"]
          and result("provision: the operator's value fills a missing field")["migrated"][-1] == "commit_git_dir (from the command line)"
          and result("provision: the operator's value fills a missing field")["record"]["ProjectBoardProvision"]["database"] == "p430_board"
          and "commit_git_dir" in result("provision: an older plan whose commit git dir nobody supplies")["message"]
          and result("provision: another field is missing")["message"].endswith("re-provision the project")
          and "_load_json" not in seams("provision: a document already read"),
          "older plans are migrated and reported, the operator fills only what is missing, and each refusal says what to do")
    check(result("load: a project config, through the launcher's loader")["ProjectConfig"]["roles"][1]["RoleConfig"]["env"]["MINE"] == "1"
          and "_with_project_board_env" in seams("load: a project config, through the launcher's loader")
          and "_role_from_json" in seams("load: a role the loader refuses"),
          "load_project_config reads each role and gives it the board env through the launcher's names")


def test_every_launcher_seam_is_reached() -> None:
    # Every function the nine read is a recorder on the launcher (the nine themselves included); the CLI tables are
    # rebound there by their own cases, and change the answer.
    names = {name for reads in SEAMS.values() for name in reads}
    constants = {name for name in names if not callable(getattr(t, name))}
    check(names - constants <= REACHED, f"a recorder on the launcher reached every function: missing {sorted(names - constants - REACHED)}")
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})}
    check(constants <= rebound and constants == {"SUPPORTED_CONFIG_CLI_NAMES", "DEFAULT_MODEL_ARG_BY_CLI", "DEFAULT_RESUME_FLAG_BY_CLI",
                                                 "DEFAULT_RESUME_MODE_BY_CLI", "DEFAULT_RESUME_SUBCOMMAND_BY_CLI"},
          f"and every constant rebound: {sorted(constants)} {sorted(rebound)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_set_of_objects_and_no_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_nine_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"project_config_json_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
